#!/usr/bin/env python3
"""
Round 143b (culprits), 2 October 2026. Needs round 142b.

Combine the ticked layers: layers in groups, so alike layers count as one.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 143b (2 October)\n\nNeeds round 142b. No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers: groups (asked 2 October: with three ticked, two\n  alike layers such as mine sites and mining features crossed each other and\n  drowned out the crossings with the third, protected areas). Each layer\n  taking part is in a group (A to H), and layers in one group count as one:\n  a square counts the groups present (comboGroups; present per group, then\n  summed), so only crossings between different groups show. Layers start in\n  the group of their heading in the layers menu (comboHeadingOf: the nearest\n  heading, not a bundle); the menu under each row (data-combo-weight, now\n  "group A" to "group H" or "left out") moves any of them. If every layer is\n  in one group the box says to split them. The brighter edge marks where the\n  most groups cross.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round143b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 142b" not in h.read_text(encoding="utf-8"):
        sys.exit("round143b: round 142b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round143b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round143b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round143b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ""

if __name__ == "__main__":
    main()
